class Solution { private var index=0;private val flips=mutableListOf<Int>();fun flipMatchVoyage(root:TreeNode?,voyage:IntArray):List<Int>{index=0;flips.clear();return if(dfs(root,voyage))flips else listOf(-1)};private fun dfs(node:TreeNode?,voyage:IntArray):Boolean{node?:return true;if(index>=voyage.size||node.`val`!=voyage[index++])return false;if(node.left!=null&&index<voyage.size&&node.left!!.`val`!=voyage[index]){flips.add(node.`val`);return dfs(node.right,voyage)&&dfs(node.left,voyage)};return dfs(node.left,voyage)&&dfs(node.right,voyage)} }
